def popular_sistemas(apps, schema_editor):
    """
    - Garante que existe pelo menos 1 Sistema (L42).
    - Missao.sistema vazio -> sistema default.
    - Checklist.sistema vazio -> herda da missão (se houver) ou default.
    - ChecklistItem.sistema (texto) -> vira FK Sistema.
    """
    Sistema = apps.get_model("operacao", "Sistema")
    Missao = apps.get_model("operacao", "Missao")
    Checklist = apps.get_model("operacao", "Checklist")
    ChecklistItem = apps.get_model("operacao", "ChecklistItem")

    # 1) Sistema default
    sistema_default, _ = Sistema.objects.get_or_create(
        nome="L42",
        defaults={"descricao": "Embarcação principal (padrão)"},
    )

    # 2) Missões sem sistema
    Missao.objects.filter(sistema__isnull=True).update(sistema=sistema_default)

    # 3) Checklists sem sistema
    for c in Checklist.objects.all():
        if c.sistema_id:
            continue
        if c.missao_id and c.missao.sistema_id:
            c.sistema_id = c.missao.sistema_id
        else:
            c.sistema_id = sistema_default.pk
        c.save(update_fields=["sistema_id"])

    # 4) ChecklistItem.sistema texto -> FK
    for item in ChecklistItem.objects.all():
        texto = (getattr(item, "sistema_texto_antigo", "") or "").strip()
        if not texto:
            item.sistema_id = None
        else:
            sistema, _ = Sistema.objects.get_or_create(
                nome=texto[:80],
                defaults={"descricao": f"Criado automaticamente: {texto[:80]}"},
            )
            item.sistema_id = sistema.pk
        item.save(update_fields=["sistema_id"])


